const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.7071068,0,0,0.7071068],down:[0.7071068,0,0,0.7071068],left:[0,0,0.7071068,0.7071068],right:[0,0,-0.7071068,0.7071068]};
const px=c=>(c-1)*1.1, pz=r=>(1-r)*1.1;
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:'Reach the orange goal square.',won:false};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const a=event.action;
 if(state.won)return {...state,msg:'Goal reached in '+state.moves+' moves (shortest is 4). Press Reset to play again.'};
 if(a==='hint')return {...state,hint:true,msg:'The green arrow shows a move one step closer to the goal.'};
 const d=D[a]; if(!d)return state;
 const c=state.c+d[0], r=state.r+d[1];
 if(c<0||c>2||r<0||r>2)return {...state,hint:false,msg:'That move would leave the board.'};
 const n={...state,c,r,moves:state.moves+1,hint:false};
 const k=dist(n);
 if(k===0){n.won=true;n.msg='You reached the goal in '+n.moves+' moves. The shortest route is 4 moves.';}
 else n.msg=k+(k===1?' step':' steps')+' to go.';
 return n;
}
export function evaluate({state}){
 const s=state, x=px(s.c), z=pz(s.r);
 const y=s.won?0.47:0.35;
 const dir=s.c<2?'right':'up';
 return {nodes:{tok:{position:[x,y,z]},hintA:{visible:!!s.hint&&!s.won,position:[x,0.35,z],quaternion:Q[dir]}},
 readouts:{moves:s.moves,dist:dist(s)},
 goal:{status:s.won?'won':'playing',message:s.msg}};
}
